import './Chip.css';

// Prop names follow Figma's component properties exactly (Size, Icon, Label).
export function Chip({ Size = 'M', Icon = false, Label = 'Filter', pressed = false, onPressedChange, className, ...rest }) {
  const classes = ['chip', Size === 'L' && 'chip--l', className].filter(Boolean).join(' ');
  return (
    <button
      type="button"
      className={classes}
      aria-pressed={pressed ? 'true' : 'false'}
      onClick={() => onPressedChange?.(!pressed)}
      {...rest}
    >
      {Icon && (
        <svg className="chip__icon" viewBox="0 0 12 12" aria-hidden="true" focusable="false">
          <circle cx="6" cy="6" r="6" fill="currentColor" />
        </svg>
      )}
      {Label}
    </button>
  );
}

export default Chip;

