import { useId } from "react";
import "../styles/tokens.css";
import "./Field.css";

/**
 * Field — a one-line text input (Figma: field, node 3:21).
 * `State` keeps Figma's prop name and values: "Default" | "Error".
 * Give it an accessible name with `label` (aria-label) or `aria-labelledby`.
 * `errorMessage` is shown while State="Error" and linked with aria-describedby.
 */
export function Field({
  State = "Default",
  label,
  errorMessage,
  className,
  id,
  "aria-describedby": describedBy,
  ...rest
}) {
  const autoId = useId();
  const fieldId = id ?? autoId;
  const isError = State === "Error";
  const messageId = `${fieldId}-message`;
  const showMessage = isError && errorMessage;

  const classes = ["field", isError && "field--error", className].filter(Boolean).join(" ");
  const describedByIds = [describedBy, showMessage && messageId].filter(Boolean).join(" ") || undefined;

  return (
    <>
      <input
        type="text"
        id={fieldId}
        className={classes}
        aria-label={label}
        aria-invalid={isError ? "true" : undefined}
        aria-describedby={describedByIds}
        {...rest}
      />
      {showMessage && (
        <span id={messageId} className="field-message">
          {errorMessage}
        </span>
      )}
    </>
  );
}

export default Field;

