  background-color: #d6f5e3;
  color: #136c3a;
}

files.src/components/Tag.jsx:
import './Tag.css';

// Prop names follow Figma's component properties exactly (Tone, Label).
export function Tag({ Tone = 'Neutral', Label = 'New', className }) {
  const classes = ['tag', Tone === 'Positive' && 'tag--positive', className]
    .filter(Boolean)
    .join(' ');
  return <span className={classes}>{Label}</span>;
}

export default Tag;

